"title": "Average Memory Usage by Region",
"viz": "table",
"layout": {"x": 0, "y": 0, "w": 12, "h": 4},
"description": "Computes the average memory usage percentage per region from system_metrics, ordered from highest to lowest average.",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT region, AVG(mem_pct) AS avg_mem_pct FROM system_metrics GROUP BY region ORDER BY avg_mem_pct DESC"
},
"options": {
"columns": [
{"name": "region", "label": "Region", "align": "left"},
{"name": "avg_mem_pct", "label": "Avg Memory Usage", "format": "percent", "decimals": 1, "align": "right"}
],
"sort": {"column": "avg_mem_pct", "order": "desc"}
}
}
